export function fuelCost(fuelById,prices=[]){const used=Object.entries(fuelById),matched=used.map(([id])=>prices.find(p=>p.fuelId===id));if(matched.some(p=>!p))return {amount:null,currency:null,reason:'fuel_price_missing'};const currencies=new Set(matched.map(p=>p.currency));if(currencies.size!==1)return {amount:null,currency:null,reason:'mixed_currencies'};return {amount:used.reduce((sum,[id,kg],i)=>sum+kg/1000*matched[i].perTonne,0),currency:matched[0].currency,reason:null,priceDates:matched.map(p=>p.date)};}
export function change(reference,candidate){if(!Number.isFinite(reference)||!Number.isFinite(candidate))return {difference:null,saving:null,percent:null};return {difference:candidate-reference,saving:reference-candidate,percent:reference===0?null:(candidate-reference)/reference*100};}
export function compareVoyages(reference,candidate){
  if(reference?.status!=='computed'||candidate?.status!=='computed')return {status:'blocked',reason:'two_routes_required'};
  if(reference.route.role!=='reference'||reference.route.source.kind!=='user-verified-reference'||!['user-attested','engine-reviewed'].includes(reference.route.source.verification))return {status:'blocked',reason:'reference_unverified'};
  if(candidate.route.role!=='hydra'||!['hydra-import','hydra-engine'].includes(candidate.route.source.kind)||!['user-attested','engine-reviewed'].includes(candidate.route.source.verification)||!candidate.route.source.engineVersion)return {status:'blocked',reason:'hydra_provenance_required'};
  if(reference.comparisonKey!==candidate.comparisonKey)return {status:'blocked',reason:'comparison_inputs_differ'};
  if(JSON.stringify(reference.endpoints)!==JSON.stringify(candidate.endpoints))return {status:'blocked',reason:'route_endpoints_differ'};
  const a=reference.totals,b=candidate.totals;return {status:'computed',scope:reference.scope,fuel:change(a.fuelKg,b.fuelKg),co2:change(a.co2Kg,b.co2Kg),time:change(a.durationHours,b.durationHours),distance:change(a.distanceNm,b.distanceNm),cost:reference.cost.currency&&reference.cost.currency===candidate.cost.currency?change(reference.cost.amount,candidate.cost.amount):{difference:null,saving:null,percent:null},currency:reference.cost.currency};
}
